types.definition:
export interface AsamActionBarExpose {
    focus: () => void;
}

export interface AsamActionBarProps {
    /** Sticky in the nearest scrolling ancestor; measured height reserves scroll clearance. */
    fixed?: boolean;
    label?: string;
}

export interface AsamActionBarSlots {
    default?: () => VNode[];
}

export interface AsamAdminLayoutEmits {
    (e: 'state-change', state: AsamLayoutState): void;
    (e: 'update:settings', settings: AsamLayoutSettings): void;
}

export interface AsamAdminLayoutExpose {
    closeSidebar: () => void;
    focusContent: () => void;
}

export interface AsamAdminLayoutProps {
    /** Partial application override; omitted fields use the documented defaults. */
    settings?: Partial<AsamLayoutSettings>;
    /** Container width breakpoint in CSS pixels, strictly below. Default 768. */
    breakpoint?: number;
    size?: AsamControlSize;
    /** Disables layout controls, not injected business content. */
    disabled?: boolean;
    readonly?: boolean;
    sidebarLabel?: string;
    menuLabel?: string;
}

export interface AsamAdminLayoutSlots {
    default?: (state: AsamLayoutState) => VNode[];
    header?: (state: AsamLayoutState) => VNode[];
    navigation?: (state: AsamLayoutState) => VNode[];
    sidebar?: (state: AsamLayoutState) => VNode[];
    footer?: (state: AsamLayoutState) => VNode[];
}

export interface AsamApplicationConfig {
    size?: AsamControlSize | null;
    colorMode?: AsamColorMode | null;
    /** Partial token objects merge recursively; null resets to ASAM defaults. */
    theme?: DeepPartial<AsamThemeTokens> | null;
    /** Element Plus public options. Shallow option replacement; null resets the bridge. */
    base?: Omit<AsamConfigProviderProps, 'size'> | null;
    permission?: AsamPermissionPolicy | null;
}

export interface AsamApplicationProviderExpose {
    state: AsamApplicationState;
}

export interface AsamApplicationProviderProps {
    config?: AsamApplicationConfig | null;
}

export interface AsamApplicationProviderSlots {
    default?: (state: AsamApplicationState) => VNode[];
}

export interface AsamApplicationState {
    config: AsamResolvedApplicationConfig;
    /** Invalid runtime input fails back to the inherited configuration and can recover. */
    errors: readonly string[];
}

export interface AsamAvatarItem {
    id: string | number;
    /** 必填姓名；也是图片失败的回退和溢出列表的文本。 */
    name: string;
    src?: string;
    description?: string;
}

export interface AsamBatchOperation {
    /** 完整冻结快照一次派发；业务适配器负责真实服务的原子性。 */
    execute(snapshot: AsamOperationSnapshot): Promise<AsamBatchResult>;
    /** 一次核实完整批次；只读目标存在不能证明原请求未发送或未应用。 */
    verify(snapshot: AsamOperationSnapshot): Promise<AsamBatchVerification>;
}

export interface AsamBatchResult {
    readonly status: 'success' | 'failure' | 'unknown';
    readonly message?: string;
}

export interface AsamBatchVerification {
    /** unsent 仅用于可信证据确认未应用；读到旧数据、读失败或丢响应不能据此释放未决锁。 */
    readonly status: AsamBatchResult['status'] | 'unsent';
    readonly message?: string;
}

export interface AsamBoundaryFailure {
    error: unknown;
    info: string;
}

export interface AsamCaptchaClock {
    /** 返回有限毫秒值；非法值/异常使当前动作进入可重试error。 */
    now(): number;
    /** 异步且仅调用一次callback；返回可交给clear的独立handle。 */
    schedule(callback: () => void, milliseconds: number): unknown;
    /** 幂等取消指定handle且不抛错；实际资源清理由适配器负责。 */
    clear(handle: unknown): void;
}

export interface AsamCaptchaController {
    readonly formatError?: (scope: AsamI18n) => string;
    readonly state: AsamCaptchaState;
    send(): Promise<boolean>;
    /** 撤销当前代次、取消请求/timer，再通知idle；idle无资源时幂等。 */
    reset(): void;
    /** 通知前关闭发送入口；销毁中重入send返回false。 */
    dispose(): void;
}

export interface AsamCaptchaControlProps {
    readonly modelValue?: string | null;
    readonly disabled?: boolean;
    readonly readonly?: boolean;
}

export interface AsamCaptchaEmits {
    'update:modelValue': [value: string];
    'state-change': [state: AsamCaptchaState];
}

export interface AsamCaptchaExpose {
    focus(): void;
    send(): Promise<boolean>;
    cancel(): void;
}

export interface AsamCaptchaOptions {
    readonly target: () => string;
    readonly service: AsamCaptchaService;
    /** 成功后冷却秒数，默认60；0表示不冷却。 */
    readonly cooldownSeconds?: number;
    readonly clock?: AsamCaptchaClock;
}

export interface AsamCaptchaRequest {
    readonly target: string;
    readonly signal: AbortSignal;
}

export interface AsamCaptchaState {
    readonly status: 'idle' | 'sending' | 'cooldown' | 'error';
    readonly remaining: number;
    readonly error: string;
}

export type AsamCardFieldOptions = (AsamOptionChoiceFieldOptions<AsamChoiceValue | null> & {
    readonly multiple?: false;
}) | (AsamOptionChoiceFieldOptions<readonly AsamChoiceValue[]> & {
    readonly multiple: true;
});

export interface AsamCardGroupProps {
    /** 分组可访问名称。 */
    label: string;
    /** 自适应最小卡宽，默认 240px，最小 120px。 */
    minWidth?: number;
    /** 几何尺寸独立于基础控件 size；显式 minWidth 优先。 */
    cardSize?: AsamCardSize;
    columns?: 'auto' | number;
    maxWidth?: AsamCssSize;
    layout?: AsamCardLayout;
    gap?: AsamCssSize;
}

export type AsamCardListProps<Row extends object> = Omit<AsamProListProps<Row>, 'layout'> & {
    readonly layout?: 'grid' | 'masonry';
};

export interface AsamCellChange<Row extends object> {
    readonly rowKey: AsamRowKey;
    readonly columnKey: keyof Row & string;
    readonly value: unknown;
    readonly previousValue: unknown;
    readonly row: Readonly<Row>;
    readonly revision: number;
    readonly signal: AbortSignal;
    /** Recheck before host storage/session side effects; transport abort alone is insufficient. */
    isCurrent(): boolean;
}

export interface AsamCellIssue {
    readonly rowKey: AsamRowKey;
    readonly columnKey: string;
    readonly message: string;
}

export interface AsamCellResult {
    readonly status: 'success' | 'failure' | 'unknown';
    /** Host-approved public text; backend exception messages are never shown automatically. */
    readonly message?: string;
}

export type AsamCellVerificationOutcome = AsamCellVerificationResult | {
    readonly status: 'blocked' | 'cancelled';
};

export interface AsamCellVerificationResult {
    readonly status: 'success' | 'not-applied' | 'unknown';
    readonly message?: string;
}

export interface AsamChoiceCardEmits {
    'update:modelValue': [value: boolean];
    change: [value: boolean];
}

export interface AsamChoiceCardProps {
    readonly actionButtonType?: AsamButtonType;
    readonly modelValue?: boolean;
    readonly label: string;
    readonly description?: string;
    readonly disabled?: boolean;
    readonly readonly?: boolean;
    readonly size?: AsamControlSize;
}

export interface AsamChoiceCardSlots {
    default?: () => VNodeChild;
}

export interface AsamChoiceContentScope {
    readonly option: AsamChoiceOption;
    readonly selected: boolean;
}

export type AsamChoiceFieldDefinition = Extract<AsamFieldDefinition, {
    kind: 'custom';
}>;

export interface AsamChoiceFieldOptions<V> {
    /** 字段清空等普通操作的颜色语义，默认 primary。 */
    readonly actionButtonType?: AsamButtonType;
    readonly key: string;
    readonly label: string;
    readonly defaultValue?: () => V;
    readonly modes?: AsamChoiceFieldDefinition['modes'];
}

export interface AsamChoiceGroupEmits {
    'update:modelValue': [value: AsamChoiceValue | readonly AsamChoiceValue[] | null];
    change: [value: AsamChoiceValue | readonly AsamChoiceValue[] | null];
}

export interface AsamChoiceGroupExpose {
    focus(): void;
    clear(): void;
}

export interface AsamChoiceGroupProps {
    readonly actionButtonType?: AsamButtonType;
    readonly modelValue?: AsamChoiceValue | readonly AsamChoiceValue[] | null;
    readonly options: readonly AsamChoiceOption[];
    readonly multiple?: boolean;
    readonly disabled?: boolean;
    readonly readonly?: boolean;
    readonly size?: AsamControlSize;
    readonly appearance?: 'card' | 'tag';
    readonly label: string;
}

export interface AsamChoiceGroupSlots {
    content?: (scope: AsamChoiceContentScope) => VNodeChild;
}

export interface AsamChoiceOption {
    readonly value: AsamChoiceValue;
    readonly label: string;
    readonly disabled?: boolean;
    readonly description?: string;
}

export interface AsamColorFieldOptions extends AsamChoiceFieldOptions<string | null> {
    /** 字段的可序列化颜色格式；其他原生格式直接使用基础ColorPicker。 */
    readonly inputProps?: Omit<AsamColorPickerProps, 'modelValue' | 'disabled' | 'colorFormat'> & {
        readonly colorFormat?: 'hex' | 'rgb' | 'hsl' | 'hsv';
    };
}

export interface AsamColumnPreference {
    readonly key: string;
    readonly visible: boolean;
    readonly width: number;
}

export interface AsamColumnPreferenceAdapter {
    load(scope: AsamPreferenceScope): Promise<unknown>;
    save(scope: AsamPreferenceScope, document: AsamColumnPreferenceDocument): Promise<void>;
    reset(scope: AsamPreferenceScope): Promise<void>;
}

export interface AsamColumnPreferenceDocument {
    readonly schema: 1;
    readonly scope: AsamPreferenceScope;
    readonly columns: readonly AsamColumnPreference[];
}

export interface AsamColumnPreferences<Row extends object> {
    /** 完整业务列元数据；旧手工 preferences 可省略，columns 仍仅表示可见列。 */
    readonly definitions?: readonly AsamOperationColumn<Row>[];
    readonly columns: ComputedRef<readonly AsamOperationColumn<Row>[]>;
    readonly items: ComputedRef<readonly AsamColumnPreference[]>;
    readonly message: ComputedRef<string>;
    readonly pending: ComputedRef<boolean>;
    readonly dirty: ComputedRef<boolean>;
    visible(key: string, value: boolean): boolean;
    move(key: string, to: number): boolean;
    width(key: string, value: number): boolean;
    load(): Promise<void>;
    save(): Promise<void>;
    reset(): Promise<void>;
    dispose(): void;
}

export interface AsamContentEditorExpose {
    focus(): void;
    clear(): void;
    cancel(): void;
    /** 组合输入未结束时不调用服务，state.error 提示结束输入后显式重试。 */
    upload(file: File, image?: boolean): Promise<void>;
    retry(): Promise<void>;
    getValue(): AsamEditorFieldValue;
    getState(): AsamEditorFieldState;
    /** 仅 Markdown 的派生 HTML；富文本由现有公开 Editor 返回。 */
    getHTML(): string;
}

export interface AsamContentEditorProps {
    /** Whether to render the clear action. Defaults to true. */
    readonly showClear?: boolean;
    /** 预览/清空/插入/重试普通操作默认 primary；取消上传保留次要操作语义。 */
    readonly actionButtonType?: AsamButtonType;
    readonly kind: AsamEditorFieldKind;
    readonly modelValue?: AsamEditorFieldValue;
    readonly services?: AsamResourceServices;
    readonly session?: string | number;
    readonly active?: boolean;
    readonly disabled?: boolean;
    readonly readonly?: boolean;
    readonly loading?: boolean;
    readonly size?: AsamControlSize;
    readonly label?: string;
    /** UTF-16 字符数；富文本按 JSON 序列化长度计算，超限保留原内容并阻止提交。 */
    readonly maxLength?: number;
}

export interface AsamContentGridProps {
    columns?: 1 | 2 | 3 | 4;
    minColumnWidth?: number;
    density?: AsamLayoutDensity;
}

export interface AsamContentGridSlots {
    default?: () => VNode[];
}

export interface AsamCopyOptions {
    /** Promise resolve 只证明适配器报告写入成功。 */
    writeText?: (text: string) => void | Promise<void>;
}

export type AsamCopyResult = {
    status: 'success' | 'stale';
} | {
    status: 'error';
    error: unknown;
};

export interface AsamCountToEmits {
    change: [value: number];
    finish: [value: number | null];
}

export interface AsamCountToExpose {
    /** 取消当前帧并立即显示目标值。 */
    finish: () => void;
}

export interface AsamCountToProps extends AsamNumberDisplayProps {
    /** 默认 600ms；0 或非法时长立即完成，最大 60s。 */
    duration?: number;
    /** 不传时遵从 prefers-reduced-motion。 */
    reducedMotion?: boolean;
}

export interface AsamCrossPageSelection {
    readonly limit: number;
    readonly keys: ComputedRef<readonly AsamRowKey[]>;
    readonly error: ComputedRef<string>;
    readonly ready: ComputedRef<boolean>;
    context(): AsamOperationContext | null;
    selectPage(rows: readonly object[]): boolean;
    clear(): void;
    reset(): void;
    dispose(): void;
}

export interface AsamCrossPageSelectionConfig<Row extends object> {
    readonly controller: AsamListController<Row>;
    /** 宿主提供有效数据集身份，不包含页码；查询/排序仍额外核对。 */
    readonly dataset: MaybeRefOrGetter<string>;
    readonly selectionLimit?: number;
}

export interface AsamCrudBatchSnapshot<Key extends AsamCrudKey> extends Omit<AsamOperationSnapshot, 'targets' | 'rejected'> {
    readonly targets: readonly AsamCrudTarget<Key>[];
    readonly rejected: readonly {
        readonly key: Key;
        readonly reason: string;
    }[];
}

export interface AsamCrudBulkRemove<Key extends AsamCrudKey> {
    execute(snapshot: AsamCrudBatchSnapshot<Key>): Promise<AsamBatchResult>;
    verify(snapshot: AsamCrudBatchSnapshot<Key>): Promise<AsamBatchVerification>;
}

export interface AsamCrudCodec<Model extends object> {
    encode(model: Readonly<Model>): AsamFieldModel;
    decode(model: Readonly<AsamFieldModel>): Model;
}

export interface AsamCrudConfig<Row extends object, Query extends object, Edit extends object, Key extends AsamCrudKey> {
    readonly runtime: AsamDataRuntime;
    /** 应用持有协调器，跨页面卸载仍保留未决写记录。 */
    readonly writes: AsamWriteCoordinator;
    readonly operations: AsamTableOperationCoordinator;
    readonly list?: AsamListController<Row>;
    readonly rowKey: (row: Row) => Key;
    readonly isKey: (value: unknown) => value is Key;
    readonly dataset: MaybeRefOrGetter<string>;
    readonly initial: Query;
    readonly queryFields: readonly AsamFieldDefinition[];
    readonly editFields: readonly AsamFieldDefinition[];
    readonly detailFields: readonly AsamFieldDefinition[];
    readonly queryCodec: AsamCrudCodec<Query>;
    readonly editCodec: AsamCrudCodec<Edit>;
    readonly equals?: AsamEditorConfig['equals'];
    /** Display external editor/codec failures without changing their raw diagnostics. */
    readonly formatError?: (cause: unknown, scope: AsamI18n) => string;
    readonly validatePayload?: (model: Readonly<Edit>) => Promise<readonly AsamEditIssue[]>;
    readonly detail: AsamCrudDetail<Row>;
    readonly columns: readonly AsamOperationColumn<Row>[];
    /** 内部复用 StructuredTable 引擎；行、作用域和 key 都来自同一个 CRUD 列表。 */
    readonly structure?: AsamCrudStructure<Row>;
    readonly preferences: {
        readonly scope: MaybeRefOrGetter<AsamPreferenceScope>;
        readonly adapter: AsamColumnPreferenceAdapter;
    };
    readonly services: AsamCrudServices<Row, Query, Edit, Key>;
    readonly pageSize?: 10 | 20 | 50 | 100;
    readonly disabled?: MaybeRefOrGetter<boolean>;
    readonly readonly?: MaybeRefOrGetter<boolean>;
    readonly allowed: (action: AsamCrudAction, key?: Key) => boolean;
    readonly allowedRemove: (target: AsamCrudTarget<Key>, context: AsamOperationContext) => boolean;
    readonly confirmRemove: (snapshot: AsamOperationSnapshot) => Promise<boolean>;
    readonly confirmDiscard: () => Promise<boolean>;
    readonly operationId: (action: 'create' | 'edit' | 'remove', key?: Key) => string;
    readonly feedback?: (event: AsamCrudFeedback) => void;
}

export interface AsamCrudController<Row extends object, Key extends AsamCrudKey> {
    /** 缺省为可写构造；只读控制器使用独立的 readonly 判别。 */
    readonly mode?: 'writable';
    readonly list: AsamListController<Row>;
    readonly structure?: AsamStructuredController<Row> & {
        readonly mode: 'tree';
    };
    readonly editor: AsamEditorController;
    readonly detail: AsamDetailController;
    readonly selection: AsamCrossPageSelection;
    readonly preferences: AsamColumnPreferences<Row>;
    readonly operations: AsamTableOperationCoordinator;
    readonly records: ComputedRef<readonly AsamOperationRecord[]>;
    readonly disabled: ComputedRef<boolean>;
    readonly readonly: ComputedRef<boolean>;
    readonly refreshState: Readonly<Ref<AsamCrudRefresh>>;
    readonly message: Readonly<Ref<string>>;
    readonly editMode: Readonly<Ref<'create' | 'edit'>>;
    key(row: Row): Key;
    can(action: AsamCrudAction, row?: Row): boolean;
    create(operationId?: string): Promise<void>;
    edit(row: Row, operationId?: string): Promise<void>;
    showDetail(row: Row): Promise<void>;
    remove(keys?: readonly Key[], operationId?: string): Promise<AsamOperationRecord | null>;
    verifyRemove(operationId: string): Promise<AsamOperationRecord | null>;
    retryRemove(operationId: string): Promise<AsamOperationRecord | null>;
    retryRefresh(): Promise<void>;
    reset(): Promise<void>;
    /** 只释放自身effectScope；借入list/runtime/应用协调器不被销毁。 */
    dispose(): void;
}

export type AsamCrudDetail<Row extends object> = {
    readonly mode: 'load';
    readonly load: Extract<AsamDetailSource, {
        mode: 'load';
    }>['load'];
    readonly direct?: never;
} | {
    readonly mode: 'direct';
    readonly direct: (row: Row) => Omit<Extract<AsamDetailSource, {
        mode: 'direct';
    }>, 'id' | 'mode'>;
    readonly load?: never;
};

export type AsamCrudFeedback = {
    readonly kind: 'saved';
    readonly event: AsamSavedEvent;
} | {
    readonly kind: 'removed';
    readonly record: AsamOperationRecord;
    readonly keys: readonly AsamCrudKey[];
} | {
    readonly kind: 'refresh';
    readonly result: AsamCrudRefresh;
};

export interface AsamCrudListRequest<Query extends object> extends Omit<AsamListRequest, 'query'> {
    readonly query: Readonly<Query>;
}

export interface AsamCrudOverlayScope<Row extends object, Key extends AsamCrudKey, Controller extends AsamCrudViewController<Row, Key> = AsamCrudController<Row, Key>> {
    readonly controller: Controller;
    readonly fallbackFocus: () => HTMLElement | null;
    /** 详情由页面动作打开时的真实触发节点；editor scope 可省略。 */
    readonly trigger?: HTMLElement;
}

export interface AsamCrudPageProps<Row extends object, Key extends AsamCrudKey, Controller extends AsamCrudViewController<Row, Key> = AsamCrudController<Row, Key>> extends AsamTableAppearanceProps {
    readonly controller: Controller & AsamCrudViewController<Row, Key>;
    readonly title?: string;
    /** 页标题上方的简短说明。 */
    readonly description?: string;
    readonly createLabel?: string;
    readonly editLabel?: string;
    readonly detailLabel?: string;
    readonly size?: AsamControlSize;
    /** 表格行高：large/default/small/mini = 60/50/42/36px；默认 default。 */
    readonly tableSize?: AsamTableSize;
    /** 标准模式默认名称链接、右侧抽屉、小尺寸单行操作；legacy 保留旧呈现默认。 */
    readonly viewMode?: 'standard' | 'legacy';
    /** 仅呈现查询区、表格和分页，省略内置写操作及详情容器。 */
    readonly presentation?: 'full' | 'query-table';
    /** 详情容器的显式覆盖；不影响 detail 替换槽及控制器。 */
    readonly detailDisplay?: 'drawer' | 'dialog';
    /** 默认查询及数据分别使用真实 AsamCard；standard 默认 true，legacy 默认 false。 */
    readonly sectionCards?: boolean;
    /** 标准使用仅显示/隐藏列的轻量弹出列表；legacy 保留原偏好面板。 */
    readonly columnSettings?: 'popover' | 'panel';
    /** standard 默认用户结果呈现，legacy 默认诊断详情；不改变后台协调记录。 */
    readonly operationDetails?: 'user' | 'diagnostic';
    /** 透传原 FormDialog 的公开布局，不创建第二个编辑器。 */
    readonly editorColumns?: 1 | 2 | 3;
    readonly editorWidth?: string;
    /** 保存为主操作，默认 primary。 */
    readonly saveButtonType?: AsamButtonType;
    /** 透传内置编辑弹窗的取消按钮类型，默认 default。 */
    readonly cancelButtonType?: AsamButtonType;
    readonly queryColumns?: 1 | 2 | 3;
    readonly queryCollapsedCount?: number;
    readonly queryFieldLabels?: Readonly<Record<string, string>>;
    readonly fieldLabels?: Readonly<Record<string, string>>;
    /** 默认查询和新增使用 primary；不改变删除、刷新和自定义槽。 */
    readonly actionButtonType?: AsamButtonType;
    /** fill 以偏好列宽为最小值铺满；content 保留精确列宽与内容宽度。 */
    readonly tableWidth?: 'fill' | 'content';
    /** false 隐藏整个标题区；无有效 title 且无 heading 插槽时不渲染。 */
    readonly showHeading?: boolean;
    /** 根页面留白，默认 20px。宿主已提供 20px 时设为 0，避免重复；不改变卡片内间距。 */
    readonly pagePadding?: number | string;
    /** 页面内容宽度；省略时使用 defaultContentWidth，默认占满宿主可用内容区。 */
    readonly contentWidth?: 'full' | 'contained';
    /** 非受控模式的初始宽度；contained 使用 --asam-crud-content-width 限宽。 */
    readonly defaultContentWidth?: 'full' | 'contained';
    readonly actionColumnWidth?: number;
    /** 操作列默认固定右侧；false 显式关闭，不影响业务列 fixed。 */
    readonly actionColumnFixed?: 'right' | false;
    /** 默认普通列表显示分页，预加载树隐藏分页；不改变服务返回的数据。 */
    readonly pagination?: boolean;
    /** 仅一个详情列，默认首个可见数据列；render/cell 显示保留。
     * 指定列隐藏或不可用时回退首个可见数据列。false 显式关闭列入口；选择/操作列不参与。
     */
    readonly detailEntry?: false | {
        readonly column?: keyof Row & string;
    };
    /** 独立行双击入口，standard 默认 true、legacy 默认 false；真实交互控件不触发。 */
    readonly detailOnRowDblclick?: boolean;
    /** 业务列可拖宽默认 true；每列 resizable 优先，与显示边框开关独立。 */
    readonly resizable?: boolean;
    /** 仅行操作尺寸；标准默认 small，legacy 省略时沿用页面 size。 */
    readonly rowActionSize?: AsamControlSize;
    /** 标准默认 true、legacy 默认 false；超过三项或列宽不足时使用真实更多菜单。 */
    readonly rowActionOverflow?: boolean;
    /** 附加动作沿用 ListController 的权限、忙碌和不可变行快照协议。 */
    readonly rowActions?: readonly AsamListAction<Row>[];
}

export type AsamCrudRefresh = {
    readonly status: 'idle';
} | {
    readonly status: 'refreshing' | 'success' | 'stale';
    readonly operationId: string;
} | {
    readonly status: 'error';
    readonly operationId: string;
    readonly error: unknown;
};

export type AsamCrudRemoveResult<Key extends AsamCrudKey> = Omit<AsamTargetResult, 'key'> & {
    readonly key: Key;
};

export type AsamCrudResolution<Key extends AsamCrudKey> = {
    readonly key: Key;
    readonly target: AsamCrudTarget<Key>;
} | {
    readonly key: Key;
    readonly reason: string;
};

export interface AsamCrudServices<Row extends object, Query extends object, Edit extends object, Key extends AsamCrudKey> {
    /** 显式原子批次删除；配置后所有删除（包括单行）均由此入口一次派发。 */
    readonly bulkRemove?: AsamCrudBulkRemove<Key>;
    list(request: AsamCrudListRequest<Query>, context: AsamRequestContext): Promise<AsamPage<Row>>;
    defaults(context: AsamRequestContext): Promise<Edit>;
    load(key: Key, context: AsamRequestContext): Promise<Edit>;
    create(model: Readonly<Edit>, operation: AsamWriteOperation, context: AsamRequestContext): Promise<AsamSaveResult>;
    update(key: Key, model: Readonly<Edit>, operation: AsamWriteOperation, context: AsamRequestContext): Promise<AsamSaveResult>;
    verify(operation: AsamPendingWrite, context: AsamRequestContext): Promise<{
