export interface AsamListAction<Row extends object> {
    readonly id: string;
    readonly label: string;
    /** 表格按钮的展示配置；不影响权限、禁用、焦点及执行协议。行操作默认 primary plain。 */
    readonly button?: Readonly<Pick<AsamButtonProps, 'type' | 'plain' | 'link' | 'text'>>;
    /** 未声明时按结果相关操作处理；busyKey相同的操作互斥。 */
    readonly scope?: 'result' | 'selection' | 'independent';
    readonly busyKey?: string;
    /** 本次触发按钮忙碌时保留可聚焦性，以 aria-disabled 和调用守卫阻止重复执行。
     * 用于由宿主原生确认框管理焦点返回的动作；其他按钮及非忙碌禁用态不变。
     */
    readonly retainFocusWhileBusy?: boolean;
    readonly visible?: (row?: Row) => boolean;
    readonly enabled?: (row?: Row) => boolean;
    /** Display an external failure in the active view scope; the original cause stays unchanged. */
    readonly formatError?: (cause: unknown, scope: AsamI18n) => string;
    readonly run: (context: {
        readonly row?: Row;
        readonly selected: readonly Row[];
        readonly scope: string;
        readonly epoch: number;
        /** 视图产生的本次触发元素；直接调用控制器时可省略。 */
        readonly trigger?: HTMLElement;
    }) => Promise<unknown>;
}

export type AsamListActionResult = {
    readonly status: 'success' | 'blocked' | 'cancelled' | 'conflict' | 'invalid';
} | {
    readonly status: 'error';
    readonly error: unknown;
};

export interface AsamListColumn<Row extends object> {
    /** 业务列的原生 resizable；在 ProTable/Operations 内不依赖显示边框开关。 */
    readonly resizable?: boolean;
    readonly fixed?: boolean | 'left' | 'right';
    readonly key: keyof Row & string;
    readonly label: string;
    readonly sortable?: boolean;
    readonly width?: number;
    readonly render?: (row: Row) => VNodeChild;
}

export interface AsamListConfig<Row extends object> {
    readonly fields: MaybeRefOrGetter<readonly AsamFieldDefinition[]>;
    readonly initial: AsamFieldModel;
    readonly api: AsamApiRequest<AsamListRequest, AsamPage<Row>>;
    readonly rowKey: string | ((row: Row) => AsamRowKey);
    readonly runtime?: AsamDataRuntime;
    readonly immediate?: boolean;
    readonly pageSize?: 10 | 20 | 50 | 100;
    readonly queryKeys?: readonly string[];
    readonly validate?: AsamListValidation;
}

export interface AsamListContent {
    readonly title: string;
    readonly description?: string;
    readonly meta?: readonly AsamListMeta[];
    readonly cover?: {
        readonly src: string;
        readonly alt: string;
    };
    readonly avatars?: readonly AsamAvatarItem[];
}

export interface AsamListController<Row extends object = object> {
    readonly fields: ComputedRef<readonly AsamFieldDefinition[]>;
    readonly draft: Ref<AsamFieldModel>;
    readonly intent: Readonly<Ref<AsamListIntent | null>>;
    readonly successfulSource: Readonly<Ref<AsamListIntent | null>>;
    readonly dirty: ComputedRef<boolean>;
    readonly issues: Readonly<Ref<readonly AsamFieldIssue[]>>;
    readonly validating: Readonly<Ref<boolean>>;
    readonly scopeReady: Readonly<Ref<boolean>>;
    readonly session: Readonly<Ref<number>>;
    readonly page: AsamPagedState<Row>;
    readonly rowKey: AsamListConfig<Row>['rowKey'];
    readonly resultReady: ComputedRef<boolean>;
    readonly actionError: Readonly<Ref<string>>;
    formatActionError?(scope: AsamI18n): string;
    readonly busy: Readonly<Ref<ReadonlySet<string>>>;
    setDraft(model: AsamFieldModel): void;
    submit(validate?: AsamListValidation): Promise<AsamListActionResult>;
    reset(validate?: AsamListValidation): Promise<AsamListActionResult>;
    refresh(): Promise<AsamListActionResult>;
    retry(): Promise<AsamListActionResult>;
    setPage(page: number): Promise<AsamListActionResult>;
    setPageSize(size: number): Promise<AsamListActionResult>;
    setSort(sort: AsamListSort | null): Promise<AsamListActionResult>;
    setResetBaseline(model: AsamFieldModel): void;
    replaceConditions(model: AsamFieldModel, options: {
        readonly mode: 'draft' | 'submit';
        readonly force?: boolean;
    }): Promise<AsamListActionResult>;
    resumeScope(initial: AsamFieldModel): void;
    registerValidation(validate: AsamListValidation): () => void;
    clearSelection(): void;
    select(rows: readonly Row[]): void;
    canAction(action: AsamListAction<Row>, row?: Row): boolean;
    runAction(action: AsamListAction<Row>, row?: Row, trigger?: HTMLElement): Promise<AsamListActionResult>;
}

