export interface AsamOperationsTableProps<Row extends object> extends AsamTableAppearanceProps {
    readonly readonly?: false;
    readonly controller: AsamListController<Row>;
    readonly selection: AsamCrossPageSelection;
    readonly coordinator: AsamTableOperationCoordinator;
    readonly preferences: AsamColumnPreferences<Row>;
    readonly operations: readonly AsamTableOperation[];
    /** 宿主生成可稳定复用的ID；同一ID不会再次发送。 */
    readonly operationId: (action: string) => string;
    readonly actions?: readonly AsamListAction<Row>[];
    readonly rowActions?: readonly AsamListAction<Row>[];
    readonly size?: AsamControlSize;
    /** 表格行高独立于工具栏、分页和按钮尺寸；默认 default (50px)。 */
    readonly tableSize?: AsamTableSize;
    /** content 保持精确偏好列宽；fill 以偏好为最小宽度并由原生表格分配剩余空间。 */
    readonly widthMode?: 'content' | 'fill';
    readonly actionColumnWidth?: number;
    /** 操作列默认固定右侧，false 显式关闭；业务列 fixed 独立保留。 */
    readonly actionColumnFixed?: 'right' | false;
    /** 预加载树引擎；所有 original 必须为本列表当前结果的 canonical Row。 */
    readonly structure?: AsamStructuredController<Row> & {
        readonly mode: 'tree';
    };
    /** 默认显示公共分页栏；false 用于树或宿主管理分页的场景。 */
    readonly pagination?: boolean;
    /** 行操作独立尺寸；不影响工具栏、查询和分页。 */
    readonly rowActionSize?: AsamControlSize;
    /** 显式启用单行及真实更多菜单；省略时保留旧换行呈现。 */
    readonly rowActionOverflow?: boolean;
    /** 默认 true；列自身 resizable 优先，与高级表的显示边框开关独立。 */
    readonly resizable?: boolean;
    readonly columnSettings?: 'popover' | 'panel';
    /** 仅列设置入口/浮层的禁用态；默认不禁用，不替代业务控制器权限。 */
    readonly columnSettingsDisabled?: boolean;
    /** 自定义普通用户结果区的可访问名称；省略保留原诊断记录名称。 */
    readonly operationRecordLabel?: string;
}

export interface AsamOperationsTableSlots<Row extends object> {
    toolbar?: () => VNodeChild;
