    /** 宿主可渲染读取错误并调用同一结果的重试入口。 */
    error?: (context: {
        error: NonNullable<AsamListController<Row>['page']['error']['value']>;
        retry: AsamListController<Row>['retry'];
    }) => VNodeChild;
    empty?: () => VNodeChild;
    record?: (context: {
