        readonly text: string;
        readonly format: AsamTransferFormat;
    }>;
}

export interface AsamTransferInput {
    readonly text: string;
    readonly format: AsamTransferFormat;
    readonly header: boolean;
    /** 每个输入列必须显式映射到字段；不支持隐式丢列。 */
    readonly mapping: readonly string[];
    readonly mode: 'existing' | 'external';
}

export interface AsamTransferIssue {
    readonly row: number;
    readonly column: number;
    readonly line: number;
    readonly sourceColumn: number;
    readonly field?: string;
    readonly message: string;
}

export interface AsamTransferLimits {
    readonly bytes: number;
    readonly rows: number;
    readonly columns: number;
}

export interface AsamTransferOperation {
    readonly operationId: string;
    readonly scope: string;
    readonly identity: string;
    readonly row: AsamTransferRow;
}

export interface AsamTransferOutput {
    readonly range: AsamTransferRange;
    readonly headers: readonly string[];
    readonly rows: readonly (readonly string[])[];
}

export interface AsamTransferReceipt {
    readonly operation: AsamTransferOperation;
    readonly result: AsamTransferWriteResult;
}

export interface AsamTransferRow {
    readonly index: number;
    readonly cells: readonly AsamTransferCell[];
    readonly model: Readonly<AsamFieldModel>;
    readonly payload?: Readonly<AsamFieldModel>;
    readonly key?: AsamRowKey;
}

export interface AsamTransferSession {
    readonly scope: string;
    readonly identity: string;
    readonly revision: number;
    readonly readable: boolean;
}

export declare class AsamTransferTextError extends Error {
    readonly line: number;
    readonly column: number;
    constructor(message: string, line: number, column: number);
}

export interface AsamTransferWriter {
    /** 准备阶段不可写；返回的 dispatch 才能调用服务。 */
    prepare(operation: AsamTransferOperation, context: AsamTransferContext): Promise<() => Promise<AsamTransferWriteResult>>;
    verify?(operation: AsamTransferOperation, context: AsamTransferContext): Promise<AsamTransferWriteResult>;
}

export type AsamTransferWriteResult = {
    readonly status: 'success';
    readonly message?: string;
} | {
    readonly status: 'not-applied' | 'unknown';
    readonly message: string;
};

export interface AsamTrendProps extends AsamNumberDisplayProps {
    direction: 'up' | 'down' | 'flat';
    /** 上涨不一定是好事；语义与方向独立。 */
    tone?: 'positive' | 'negative' | 'neutral';
    label?: string;
}

export interface AsamVirtualColumn<Row extends object> extends AsamListColumn<Row> {
    readonly width: number;
    readonly fixed?: 'left' | 'right';
}

export interface AsamVirtualFocus<Row extends object> {
    readonly row: Row;
    readonly key: AsamRowKey;
    readonly index: number;
}

export interface AsamVirtualSortIntent {
    readonly key: string;
    readonly order: 'ascending' | 'descending' | undefined;
}

export type AsamVirtualSource<Row extends object> = {
    readonly rows: readonly Row[];
    readonly rowKey: (keyof Row & string) | ((row: Row) => AsamRowKey);
    readonly controller?: never;
} | {
    readonly controller: AsamListController<Row>;
    readonly rows?: never;
    readonly rowKey?: never;
};

export type AsamVirtualTableEvents<Row extends object> = {
    'sort-change': (intent: AsamVirtualSortIntent) => void;
    'focus-change': (focus: AsamVirtualFocus<Row>) => void;
    retry: () => void;
};

export interface AsamVirtualTableExpose {
    scrollToRow(index: number): Promise<boolean>;
    scrollToKey(key: AsamRowKey): Promise<boolean>;
    focusRow(index: number): Promise<boolean>;
    focusKey(key: AsamRowKey): Promise<boolean>;
    scrollToLeft(left: number): boolean;
    /** 实例自有异步帧计数；销毁后始终为0，不包含上游资源。 */
    getPendingOperations(): number;
    getResourceCounts(): Readonly<{
        frames: number;
        listeners: number;
        subscriptions: number;
    }>;
}

export interface AsamVirtualTableSlots<Row extends object> {
    cell?: (context: {
        row: Row;
        column: AsamVirtualColumn<Row>;
        index: number;
    }) => VNodeChild;
    empty?: () => VNodeChild;
}

export interface AsamWordCountProps {
    text: string;
    /** 默认 Intl.Segmenter grapheme；空白和换行计数，CRLF算一个字素。 */
    count?: AsamCountMethod;
    /** 非负整数，否则无上限。只报告超限，不修改或截断宿主文本。 */
    max?: number;
    label?: string;
}

export interface AsamWordCountResult {
    length: number | null;
    max: number | null;
    exceeded: boolean;
    /** Segmenter 缺失或自定义函数失败时明确不可用，不偷换 UTF16 口径。 */
    available: boolean;
}

export interface AsamWordCountSlots {
    default?: (result: AsamWordCountResult) => VNode[];
}

export interface AsamWriteCoordinator {
    get(scope: string, operationId: string): AsamPendingWrite | undefined;
    set(operation: AsamPendingWrite): void;
    /** 同一操作的成功结果只交付一次。 */
    claimSuccess(scope: string, operationId: string): boolean;
}

export interface AsamWriteOperation {
    readonly target: AsamEditTarget;
    readonly scope: string;
    readonly startedAt: number;
    readonly input: Readonly<AsamFieldModel>;
    readonly payload: Readonly<AsamFieldModel>;
}

export interface GuidanceRequest {
    signal: AbortSignal;
}

export interface GuidanceStep {
    key: string;
    title: string;
    description?: string;
    target: GuidanceTarget;
    placement?: AsamTourPlacement;
}

export interface GuidedTourEmits {
    'update:modelValue': [open: boolean];
    'update:current': [current: number];
    exit: [reason: TourExitReason];
    missing: [step: GuidanceStep];
}

export interface GuidedTourExpose {
    next: () => void;
    previous: () => void;
    close: () => void;
}

export interface GuidedTourProps {
    modelValue: boolean;
    current?: number;
    steps: readonly GuidanceStep[];
    disabled?: boolean;
    size?: GuidanceSize;
    label?: string;
}

export interface HelpContent {
    title: string;
    text: string;
    href?: string;
}

export interface HelpPanelEmits {
    'update:modelValue': [open: boolean];
    loaded: [content: HelpContent | null];
    error: [error: unknown];
}

export interface HelpPanelExpose {
    reload: () => Promise<void>;
}

export interface HelpPanelProps {
    modelValue: boolean;
    contextKey: string;
    content?: HelpContent | null;
    load?: HelpLoader;
    label?: string;
    disabled?: boolean;
    size?: GuidanceSize;
}

export interface NotificationCategory {
    key: string;
    label: string;
}

export interface NotificationItem {
    key: NotificationKey;
    title: string;
    description?: string;
    category: string;
    unread: boolean;
    disabled?: boolean;
}

export interface NotificationOperation extends NotificationQuery {
    action: NotificationAction;
    keys: readonly NotificationKey[];
}

export interface NotificationPanelEmits {
    'update:category': [category: string | null];
    request: [operation: Omit<NotificationOperation, 'signal'>];
    result: [operation: Omit<NotificationOperation, 'signal'>];
    error: [error: unknown];
}

export interface NotificationPanelExpose {
    reload: () => Promise<void>;
}

export interface NotificationPanelProps {
    items?: readonly NotificationItem[];
    categories?: readonly NotificationCategory[];
    category?: string | null;
    load?: NotificationLoader;
    operate?: NotificationOperator;
    unreadTotal?: number;
    disabled?: boolean;
    readonly?: boolean;
    size?: GuidanceSize;
    label?: string;
}

export interface NotificationQuery extends GuidanceRequest {
    category: string | null;
}

export interface NotificationSnapshot {
    items: readonly NotificationItem[];
    unreadTotal?: number;
}

