}

interface AsamDetailOverlayProps {
    /** 详情控制器管理开合。通过 controller.open() 打开当前记录。 */
    readonly controller: AsamDetailController;
    /** 浮层标题，默认使用当前语言的资料详情标题。 */
    readonly title?: string;
    /** 按字段键覆盖资料标签。 */
    readonly fieldLabels?: Readonly<Record<string, string>>;
    /** 空值的占位文案。 */
    readonly emptyText?: string;
    /** 详情字段的列数，默认双列。 */
    readonly columns?: 1 | 2 | 3;
    /** 详情面板的呈现样式，默认 grouped。 */
    readonly appearance?: AsamDetailAppearance;
    /** 禁止通过关闭按钮、页脚 close 回调、遮罩或 Escape 关闭。 */
    readonly closeDisabled?: boolean;
    /** 点击遮罩时能否关闭，默认沿用基础容器。 */
    readonly closeOnClickModal?: boolean;
    /** 按 Escape 时能否关闭，默认沿用基础容器。 */
    readonly closeOnPressEscape?: boolean;
}

interface DetailTarget {
    readonly id: string | number;
}

interface AsamEditorFormOptions extends Omit<AsamEditorActionProps, 'controller'> {
    readonly fieldLabels?: Readonly<Record<string, string>>;
    /** 默认双列，按表单自身容器窄屏降为单列；field.layout.span 可跨列。 */
    readonly columns?: 1 | 2 | 3;
    readonly showActions?: boolean;
    /** 加载完成后聚焦首个可编辑字段，默认不抢占页面焦点。 */
    readonly autoFocus?: boolean;
    readonly issues?: readonly AsamEditIssue[];
    readonly readonly?: boolean;
    readonly busy?: boolean;
    readonly active?: boolean;
    readonly session?: string | number;
}

export interface AsamEditorActionProps {
    readonly controller: AsamEditorController;
    readonly saveButtonType?: AsamButtonType;
    readonly cancelButtonType?: AsamButtonType;
    readonly cancelButtonPlain?: boolean;
    readonly size?: AsamControlSize;
    readonly disabled?: boolean;
}

interface FieldBase<V> {
    readonly key: string;
    readonly label: string;
    readonly defaultValue?: () => V;
    readonly modes?: Partial<Readonly<Record<AsamFieldMode, AsamFieldModeConfig>>>;
    /** 自定义控件支持原生 teleported、popperClass 与 visible-change 时声明。 */
    readonly popup?: boolean;
    readonly adaptInput?: (value: unknown) => V;
    readonly clone?: (value: unknown) => unknown;
    readonly format?: (value: V, context?: AsamFieldFormatContext) => string;
    readonly query?: (value: V, context: AsamFieldContext) => unknown;
    readonly submit?: (value: V, context: AsamFieldContext) => unknown;
    /** 隐藏字段只有显式提交映射且本开关为 true 才参与提交。 */
    readonly submitHidden?: boolean;
}

interface ChoiceSource {
    readonly source?: AsamFieldSource;
    readonly remote?: AsamFieldRemote;
}

